def validate_approval(a,c):
    tc.require(a.get('kind')=='root-approved-thigh-proximal-backward-Y20-diagnostic' and a.get('reviewedBy')=='/root' and a.get('authorizeImplementationAndOneFreshExport') is True and a.get('configuration')==c,'Exact executed root20approval required')
    exact={'part':'legl','joint':'lthigh_g','coordinateSpace':'working','statureApplications':0,'factor85Reapplied':False,'deltaWorldMetres':[0.,-.020,0.],'supportOriginWorld':[0.,0,0.],'supportAxisWorld':[0.,0,1.],'innerPlateauHalfWidthMetres':.005,'outerSupportHalfWidthMetres':.035}
    tc.require(all(c.get(k)==v for k,v in exact.items()),'Exact scoped world-Y20/Zband recipe required')
    tc.require(c.get('supportCenterWorldZMetres')==.9335863177830892,'Exact measured actual35LEFTport center required')

def field(c):
    return ConnectorShear(np.asarray(c['supportOriginWorld']),np.asarray(c['supportAxisWorld']),np.asarray(c['deltaWorldMetres']),c['supportCenterWorldZMetres'])

def input_pin(p,h,pins,c):
    p=Path(p).resolve();actual=tc.sha(p)
    if actual!=h:
        alias=c.get('historicalExecutedSourceRecoveries',{}).get(str(p));tc.require(p.name in ['pose_preview.py','pose_preview_target_parts.py'] and alias is not None and alias['originalSourcePath']==str(p) and alias['executedSha256']==h,'Only exact approved2historic renderer snapshots may recover source version')
        snapshot=Path(alias['snapshot']['path']).resolve();tc.require(alias['snapshot']['sha256']==h and tc.sha(snapshot)==h,'Historical executed snapshot differs');pins[str(snapshot)]=h;proof=alias['recoveryEvidence'];tc.require(tc.sha(proof['path'])==proof['sha256'],'Historical recovery proof changed');pins[proof['path']]=proof['sha256'];return snapshot
    tc.require(str(p) not in pins or pins[str(p)]==h,'Conflicting pin');pins[str(p)]=h;return p

def parent(c,tp,target,pins):
    path=input_pin(c['parentRadialDiagnosticReceipt']['path'],c['parentRadialDiagnosticReceipt']['sha256'],pins,c);r=json.loads(path.read_text());tc.verify_binding(r,tp,target,'working');tc.require(r['kind']=='troll-left-leg-axis-radial-diagnostic' and r['part']=='legl' and r['joint']=='lthigh_g' and r['factor']==.85 and r['statureApplications']==0 and r['selectionMade'] is False and all(r[k] is False for k in ['anatomyAccepted','connectorAccepted','materialAccepted','clientAccepted','productionAccepted']),'Explicit unaccepted LEFT85parent required')
    source=input_pin(c['parentCandidate']['path'],c['parentCandidate']['sha256'],pins,c);tc.require(str(source)==r['candidate'] and tc.sha(source)==r['candidateSha256'],'Parent candidate association');H=tc.frame(target,'lthigh_g','working');K=tc.frame(target,'lshin_g','working');tc.require(np.array_equal(H,r['attachmentWorld']) and np.array_equal(H,c['attachmentWorld']) and np.array_equal(H[:3,:3],np.eye(3)),'Frozen working thigh frame')
    for p,h in r['frozenInputs'].items():input_pin(p,h,pins,c)
    fp=input_pin(r['parentGeometryReceipt'],r['parentGeometryReceiptSha256'],pins,c);original=input_pin(r['parentCandidate'],r['parentCandidateSha256'],pins,c);fit=verify_source_receipt(original,fp,tp,target,'legl','working');tc.require(fit['operation']=='fit' and fit['reflectionWorld'] is None,'Exact proper uniform fit ancestry');M,d,L=radial_matrix(H[:3,3],K[:3,3],.85);ML=np.linalg.inv(H)@M@H;tc.require(np.array_equal(M,r['worldAffine']) and np.array_equal(ML,r['localAffine']) and np.array_equal(d,r['axisUnitWorld']) and L==r['jointSpanMetres'],'Exact original85field provenance')
    od,ob=read_glb(original);doc,blob=read_glb(source);tc.require(doc['nodes']==od['nodes']==[{'name':'detached_geometry','mesh':0}] and len(doc['meshes'][0]['primitives'])==1,'Single identity detached source');op=od['meshes'][0]['primitives'][0];p=doc['meshes'][0]['primitives'][0];F=accessor(doc,blob,p['indices']).reshape(-1,3).astype(np.int64);tc.require(p['indices']==op['indices'] and p['material']==op['material'] and p['attributes']['TEXCOORD_0']==op['attributes']['TEXCOORD_0'] and embedded_maps(doc,blob)==embedded_maps(od,ob),'85indexUVmapmaterial provenance')
    P=accessor(doc,blob,p['attributes']['POSITION']);N=accessor(doc,blob,p['attributes']['NORMAL']);T=accessor(doc,blob,p['attributes']['TANGENT']);UV=accessor(doc,blob,p['attributes']['TEXCOORD_0']);oldP=accessor(od,ob,op['attributes']['POSITION']);expected=(transform_positions(oldP.astype(float)@BASIS.T,ML)@BASIS).astype('<f4');active=np.zeros(len(P),bool);active[np.unique(F)]=True;tc.require(P[active].tobytes()==expected[active].tobytes(),'Exact85position provenance')
    oldN=accessor(od,ob,op['attributes']['NORMAL']).astype(float)@BASIS.T;oldT=accessor(od,ob,op['attributes']['TANGENT']).astype(float);oldT[:,:3]=oldT[:,:3]@BASIS.T;en,et=transport(oldN[active],oldT[active],ML[:3,:3]);et[:,:3]=et[:,:3]@BASIS;tc.require(N[active].tobytes()==(en@BASIS).astype('<f4').tobytes() and T[active].tobytes()==et.astype('<f4').tobytes(),'Exact85normalT provenance')
    ap=input_pin(r['nativeCornerArchive']['path'],r['nativeCornerArchive']['sha256'],pins,c)
    with np.load(ap,allow_pickle=False) as a:arc={k:a[k].copy() for k in a.files}
    local=P.astype(float)@BASIS.T;nn=N.astype(float)@BASIS.T;tt=T.astype(float).copy();tt[:,:3]=tt[:,:3]@BASIS.T;tc.require(np.array_equal(arc['sourceTriangleIds'],np.arange(len(F))) and np.array_equal(arc['sourceCornerOrder'],np.tile([0,1,2],(len(F),1))) and np.array_equal(arc['primitiveIds'],np.zeros(len(F),int)),'Exact original corner ownership');tc.require(np.max(abs(arc['positions']-local[F]))<4e-8 and np.max(abs(arc['normals']-nn[F]))<2e-7 and np.max(abs(arc['tangents']-tt[F]))<2e-7 and np.array_equal(arc['uvGltf'],UV[F]),'Actual85nativecorner bridge');return r,doc,blob,P,N,T,UV,F,active,H,arc

def mapped_rows(P,N,T,F,H,shear):
    world=P.astype(float)@BASIS.T+H[:3,3];active=np.zeros(len(P),bool);active[np.unique(F)]=True;w,_=shear.weight(world[:,2]);changed=active&(w!=0);shade=changed&np.any(shear.jacobian(world)!=np.eye(3),axis=(1,2));n=N.astype(float)@BASIS.T;t=T.astype(float).copy();t[:,:3]=t[:,:3]@BASIS.T;nn,tt=shear.transport(world[active],n[active],t[active]);nr=n.copy();tr=t.copy();nr[active]=nn;tr[active]=tt;rows={'POSITION':P.copy(),'NORMAL':N.copy(),'TANGENT':T.copy()};rows['POSITION'][changed,2]=(P[changed,2].astype(float)+.020*w[changed]).astype('<f4');rows['NORMAL'][shade]=(nr[shade]@BASIS).astype('<f4');tr[:,:3]=tr[:,:3]@BASIS;rows['TANGENT'][shade]=tr[shade].astype('<f4')
    for sem,v in rows.items():tc.require(v[~changed].tobytes()=={'POSITION':P,'NORMAL':N,'TANGENT':T}[sem][~changed].tobytes(),'Protected PNT');tc.require(np.isfinite(v).all(),'Finite serialization')
    tc.require(rows['POSITION'][:,[0,1]].tobytes()==P[:,[0,1]].tobytes(),'WorldXZ literal');return rows,world,changed,shade

def discrete(P,Q,F,H,shear):
    before=topology(P,F);after=topology(Q,F)
    for key in TOPOLOGY_KEYS:tc.require(before[key]==after[key],'Introduced topology '+key)
    old=P.astype(float)@BASIS.T+H[:3,3];new=Q.astype(float)@BASIS.T+H[:3,3];a=old[F];b=new[F];on=np.cross(a[:,1]-a[:,0],a[:,2]-a[:,0]);gn=np.cross(b[:,1]-b[:,0],b[:,2]-b[:,0]);tc.require((np.linalg.norm(on,axis=1)>2e-15).all() and (np.linalg.norm(gn,axis=1)>2e-15).all(),'Degenerate face rejected');tc.require(np.array_equal(on[:,1],gn[:,1]),'SignedXZ changed');zero=on[:,1]==0;tc.require((np.sum(on[zero]*gn[zero],axis=1)>0).all(),'ZeroXZ planar reversal');nz=~zero;e1=a[nz,1]-a[nz,0];e2=a[nz,2]-a[nz,0];dh=(b-a)[:,:,1];d1=dh[nz,1]-dh[nz,0];d2=dh[nz,2]-dh[nz,0];den=e1[:,0]*e2[:,2]-e1[:,2]*e2[:,0];gx=(d1*e2[:,2]-d2*e1[:,2])/den;gz=(e1[:,0]*d2-e2[:,0]*d1)/den;expected=on[nz].copy();expected[:,0]-=gx*on[nz,1];expected[:,2]-=gz*on[nz,1];error=float(np.max(abs(expected-gn[nz])));dots=np.sum(expected*gn[nz],axis=1)/np.linalg.norm(expected,axis=1)/np.linalg.norm(gn[nz],axis=1);tc.require(error<1e-15 and dots.min()>.99999999,'Independent secant cofactor graph orientation');J=shear.jacobian(a.mean(1));centerExpected=np.linalg.solve(J.transpose(0,2,1),on[...,None])[...,0];centerDot=np.sum(centerExpected*gn,axis=1)/np.linalg.norm(centerExpected,axis=1)/np.linalg.norm(gn,axis=1);exceptions=np.flatnonzero(centerDot<=0);tc.require(exceptions.tolist()==[2792,2793],'Only exact reviewed2slivers may mismatch analytic centroid cone');return {'beforeTopology':before,'afterTopology':after,'signedWorldXZProjectedDoubleAreasExact':True,'zeroXZPlanarOrientationRetained':True,'minimumIndependentSecantExpectedDot':float(dots.min()),'maximumSecantExpectedNormalError':error,'sourceGeometricNormalRotatedMicrofaces':exceptions.tolist(),'centroidNormalConeMismatchAcknowledged':True,'globalIntersectionClaim':False}

def native_child(arc,H,shear):
    result={k:v.copy() for k,v in arc.items()};old64=arc['positions'].reshape(-1,3);world64=old64+H[:3,3];w64,_=shear.weight(world64[:,2]);p64=old64.copy();m64=w64!=0;p64[m64,1]-=.020*w64[m64];n64,t64=shear.transport(world64,arc['normals'].reshape(-1,3),arc['tangents'].reshape(-1,4));result.update(proximalBackParentPositions=arc['positions'].copy(),proximalBackParentNormals=arc['normals'].copy(),proximalBackParentTangents=arc['tangents'].copy());result['positions']=p64.reshape(arc['positions'].shape);result['normals']=n64.reshape(arc['normals'].shape);result['tangents']=t64.reshape(arc['tangents'].shape);return result
def execute(approval_path,output):
    ap=Path(approval_path).resolve();a=json.loads(ap.read_text());c=a['configuration'];validate_approval(a,c);pins={};input_pin(ap,tc.sha(ap),pins,c);input_pin(a['proposal']['path'],a['proposal']['sha256'],pins,c);tc.require(json.loads(Path(a['proposal']['path']).read_text())==c,'Proposal closure');fp=a['focusedFacetProof'];input_pin(fp['path'],fp['sha256'],pins,c);facet=json.loads(Path(fp['path']).read_text());tc.require(facet['kind']=='independent-readonly-proximal-backward-Y-original-skinny-facet-proof','Exact reviewed facet proof');tp=input_pin(c['targetContract'],c['targetContractSha256'],pins,c);target=tc.load(tp);tc.require(target['identity']['race']=='troll' and target['identity']['gender']=='male','Troll only');r,doc,blob,P,N,T,UV,F,active,H,arc=parent(c,tp,target,pins);shear=field(c);output=Path(output).resolve();tc.require(not output.exists(),'Fresh immutable child required');rows,world,changed,shade=mapped_rows(P,N,T,F,H,shear)
