def verify_receipt(receipt_path,target_path,target,space='working'):
    path=Path(receipt_path).resolve();r=json.loads(path.read_text());tc.require(r['schemaVersion']==1 and r['kind']==KIND and r['operation']==OPERATION and space=='working' and r['canonicalNativeLineage'] is False and all(r[k] is False for k in PENDING),'Exact pending typed working thigh child');tc.verify_binding(r,target_path,target,space);tc.require(r['part']=='legl' and r['joint']=='lthigh_g' and r['model']==tc.model(target,'legl') and r['statureApplications']==0 and r['factor85Reapplied'] is False and np.array_equal(r['candidateToAttachmentLocal'],np.eye(4)),'No fit/frame/85/runtime reapplication');c=r['fieldConfiguration'];pins={}
    for p,h in r['frozenInputs'].items():input_pin(p,h,pins,c)
    tc.require(tc.sha(r['candidate'])==r['candidateSha256'] and tc.sha(r['nativeCornerArchive']['path'])==r['nativeCornerArchive']['sha256'],'Child/archive hashes');a=json.loads(Path(r['rootApproval']['path']).read_text());validate_approval(a,c);pr,old,blob,P,N,T,UV,F,active,H,arc=parent(c,target_path,target,pins);doc,nb=read_glb(r['candidate']);rows,world,changed,shade=mapped_rows(P,N,T,F,H,field(c));tc.require(nb[:len(blob)]==blob and embedded_maps(doc,nb)==embedded_maps(old,blob),'Original BIN/maps');expected=copy.deepcopy(doc);expected['meshes'][0]['primitives'][0]['attributes']=old['meshes'][0]['primitives'][0]['attributes'];expected['accessors']=expected['accessors'][:-3];expected['bufferViews']=expected['bufferViews'][:-3];expected['buffers'][0]['byteLength']=old['buffers'][0]['byteLength'];tc.require(expected==old,'Undeclared scene/index/UV/material/accessor change');attrs=doc['meshes'][0]['primitives'][0]['attributes']
    for sem,v in rows.items():tc.require(accessor(doc,nb,attrs[sem]).tobytes()==v.tobytes(),'Exact field/shading serialized arrays')
    expectedArchive=native_child(arc,H,field(c))
    with np.load(r['nativeCornerArchive']['path'],allow_pickle=False) as childArchive:
        tc.require(set(childArchive.files)==set(expectedArchive) and all(childArchive[k].dtype==v.dtype and childArchive[k].shape==v.shape and childArchive[k].tobytes()==v.tobytes() for k,v in expectedArchive.items()),'Exact authoritative f64 field/N/T and original corner provenance')
    proof=discrete(P,rows['POSITION'],F,H,field(c));tc.require(all(proof[k]==r['proof'][k] for k in ['signedWorldXZProjectedDoubleAreasExact','zeroXZPlanarOrientationRetained','sourceGeometricNormalRotatedMicrofaces']),'Required geometric proof differs');pins.update({str(path):tc.sha(path),r['candidate']:r['candidateSha256'],r['nativeCornerArchive']['path']:r['nativeCornerArchive']['sha256']});return {'receipt':r,'candidate':Path(r['candidate']),'inputs':pins,'primitiveInventory':[{'primitive':0,'part':'legl','material':doc['meshes'][0]['primitives'][0]['material'],'faces':len(F),'changedRows':int(changed.sum())}]}
if __name__=='__main__':
    p=argparse.ArgumentParser(description=__doc__);p.add_argument('--approval',type=Path,required=True);p.add_argument('--output',type=Path,required=True);a=p.parse_args();r=execute(a.approval,a.output);print(json.dumps({'receipt':str(r),'sha256':tc.sha(r)}),flush=True)
